insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('UY', 'default', 'Plan de cuentas Ekwo para Uruguay (sin catálogo oficial)', '{}'::jsonb, true, 'companies', array['UY-BAL', 'UY-RES']::text[], null, 'Uruguay no fija por ley un plan de cuentas con códigos obligatorios: la Ley N° 16.060, de Sociedades Comerciales, art. 87, sólo exige que los administradores formulen, dentro de los cuatro meses del cierre del ejercicio, el inventario y el balance general, y el art. 89 remite a las normas contables adecuadas (hoy las Normas Internacionales de Información Financiera, adoptadas por el Decreto N° 291/014, o el régimen simplificado que ese decreto habilita a las empresas de menor dimensión), sin imponer una numeración de cuentas — a diferencia del código agrupador que el Anexo 24 de la RMF mexicana publica. Este plan es una numeración propia de Ekwo (clases 1 a 5, sin correlato oficial), pensada para que cada cuenta alcance una línea del Estado de Situación Patrimonial y del Estado de Resultados de los arts. 87 y 90 de la Ley N° 16.060', 'ley16060')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

