insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('UY', 'UY-P-10', 'Compras y servicios, tasa mínima 10 %', '{}'::jsonb, 'Adquisición de bienes de primera necesidad gravada a la tasa mínima, con derecho a crédito fiscal', 'percent', 10, 'purchase', 'domestic', date '2007-07-01', null, 'Texto Ordenado 2023, Título 10, art. 34, literal B), y art. 36, literal A) — tasa mínima 10% sobre, entre otros, arroz y harina de cereales; art. 14 — derecho a crédito fiscal sobre las compras del giro. Formulario 1376, panel «IVA Ventas e IVA Compras», línea 19', 'S', null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'to2023-t10', null, null, null, null),
  ('UY', 'UY-P-22', 'Compras y servicios, tasa básica 22 %', '{}'::jsonb, 'Adquisición de bienes o servicios del giro, gravada a la tasa básica, con derecho a crédito fiscal', 'percent', 22, 'purchase', 'domestic', date '2007-07-01', null, 'Texto Ordenado 2023, Título 10, art. 34, literal A) — tasa básica 22%; art. 14 — el impuesto correspondiente a las compras de bienes y servicios adquiridos por el sujeto pasivo, documentado en la forma del art. 13, se deduce del impuesto a pagar, en tanto integre directa o indirectamente el costo de bienes y servicios destinados a las operaciones gravadas. Formulario 1376, panel «IVA Ventas e IVA Compras», línea 19 «IVA COMPRAS deducible por operaciones gravadas»', 'S', null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'to2023-t10', null, null, null, null),
  ('UY', 'UY-S-0-EXP-BIENES', 'Exportación de bienes', '{}'::jsonb, 'Enajenación de bienes exportados, no gravada por el Impuesto al Valor Agregado', 'percent', 0, 'sale', 'export', date '2007-07-01', null, 'Texto Ordenado 2023, Título 10, art. 5° — «Estarán gravadas las entregas de bienes y las prestaciones de servicios realizadas en el territorio nacional … y no lo estarán aquellas exportaciones de bienes». El exportador no traslada IVA en la exportación y, en cambio, conserva el derecho a deducir el impuesto que integre directa o indirectamente el costo del producto exportado (art. 14, inciso quinto) — véase UY-P-22 y UY-P-10, que dan ese crédito, y el Formulario 1376, panel «Determinación de IVA», línea 27, que declara el crédito de compras atribuible a la exportación, no transcrita por este paquete (véase el README)', 'G', null, 30, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'to2023-t10', null, null, null, null),
  ('UY', 'UY-S-0-EXP-SERVICIOS', 'Exportación de servicios', '{}'::jsonb, 'Servicios de diseño, desarrollo o implementación de soportes lógicos (software) prestados a un usuario del exterior y aprovechados exclusivamente allí, calificados como exportación de servicios', 'percent', 0, 'sale', 'export', date '2007-07-01', null, 'Texto Ordenado 2023, Título 10, art. 5°, inciso primero — «no lo estarán aquellas exportaciones de servicios que determine el Poder Ejecutivo»; Decreto N° 220/998, art. 34, numeral 11, literal b) — se consideran exportación «los servicios prestados para el diseño, desarrollo o implementación de soportes lógicos específicos», siempre que sean aprovechados exclusivamente en el exterior', 'G', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'decreto220-998', null, null, null, null),
  ('UY', 'UY-S-10', 'Ventas y servicios, tasa mínima 10 %', '{}'::jsonb, 'Circulación de bienes o prestación de servicios de primera necesidad gravada a la tasa mínima (p. ej. arroz, harina, servicios de hotelería)', 'percent', 10, 'sale', 'domestic', date '2007-07-01', null, 'Texto Ordenado 2023, Título 10, art. 34, literal B) — tasa mínima del 10% (fuente: Ley N° 18.083, de 27 de diciembre de 2006, art. 25); art. 36, literal A) — están sujetos a esta tasa, entre otros bienes, «arroz; harina de cereales y subproductos de su molienda»', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'to2023-t10', null, null, null, null),
  ('UY', 'UY-S-22', 'Ventas y servicios, tasa básica 22 %', '{}'::jsonb, 'Circulación de bienes o prestación de servicios gravada a la tasa básica', 'percent', 22, 'sale', 'domestic', date '2007-07-01', null, 'Texto Ordenado 2023, Título 10, art. 34, literal A) — «Fíjanse las siguientes tasas: A) Básica del 22% (veintidós por ciento)» (fuente: Ley N° 18.083, de 27 de diciembre de 2006, art. 25); art. 1° — hecho gravado (circulación de bienes, prestación de servicios); art. 3° — el hecho generador se presume configurado en la fecha de la factura', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'to2023-t10', null, null, null, null),
  ('UY', 'UY-S-EXE-INMUEBLE', 'Arrendamiento de inmuebles', '{}'::jsonb, 'Prestación de servicios de arrendamiento de bienes inmuebles, exonerada del Impuesto al Valor Agregado', 'percent', 0, 'sale', 'exempt', date '2007-07-01', null, 'Texto Ordenado 2023, Título 10, art. 38, numeral 2), literal C) — «Exonéranse … 2) Las siguientes prestaciones de servicios: … C) Arrendamientos de inmuebles»', 'E', null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'to2023-t10', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

