insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('UY', 'UY-F1376-IVA', 'Formulario 1376 — Declaración Mensual de IVA (grupo CEDE y División Grandes Contribuyentes), sección Impuesto al Valor Agregado', array['month']::declaration_period[], 'month'::declaration_period, date '2021-10-01', null, 'El Formulario 1376 sustituyó al Formulario 2176 para las declaraciones de períodos iguales o posteriores a octubre de 2021, y comprende la declaración de IVA y los anticipos de IRAE, Impuesto al Patrimonio (IPAT) e ICOSA de los contribuyentes del grupo CEDE y de la División Grandes Contribuyentes. Este paquete transcribe únicamente los campos que alimentan la determinación del Impuesto al Valor Agregado del panel «IVA Ventas e IVA Compras» y del panel «Determinación de IVA», con los números de línea que expone la aplicación PADI de la Dirección General Impositiva; omite los anticipos de IRAE, IPAT e ICOSA, que no son Impuesto al Valor Agregado — véase «Lo que este paquete no transcribe» en el README', true,'depends_on_taxpayer'::filing_deadline_rule, null, null, 'La Dirección General Impositiva fija cada año, mediante resolución (para 2026, la que fija el calendario de vencimientos publicado como «Vencimientos 2026»), un día de vencimiento distinto según el grupo del contribuyente y la terminación de su Registro Único Tributario (RUT): los contribuyentes CEDE y de la División Grandes Contribuyentes vencen entre los días 22 y 24 de cada mes, según esa terminación', 'vencimientos2026', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

