values
  ('UY', 'UY-F1376-IVA', '8', 'base', 'Ventas e ingresos no gravados o exentos (monto neto)', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 1376, panel «IVA Ventas e IVA Compras», cuadro «Ventas e IVA Ventas», línea 8: «No gravadas»', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '9', 'base', 'Ventas de exportación y asimiladas (monto neto)', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 1376, panel «IVA Ventas e IVA Compras», cuadro «Ventas e IVA Ventas», línea 9: «De exportación y asimiladas»', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '11', 'base', 'Ventas gravadas a la tasa mínima (monto neto)', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 1376, panel «IVA Ventas e IVA Compras», cuadro «Ventas e IVA Ventas», línea 11: «Gravadas tasa mínima»', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '12', 'base', 'Ventas gravadas a la tasa básica (monto neto)', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 1376, panel «IVA Ventas e IVA Compras», cuadro «Ventas e IVA Ventas», línea 12: «Gravadas tasa básica»', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '14', 'total', 'Total de ventas e ingresos del período', '{}'::jsonb, 50, null, array['8', '9', '11', '12']::text[], '{}'::text[], null, null, false, false, null, 'Formulario 1376, panel «IVA Ventas e IVA Compras», cuadro «Ventas e IVA Ventas», línea 14 «TOTAL» — este paquete suma únicamente las líneas que sus impuestos alimentan', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '15', 'tax', 'IVA ventas — tasa mínima', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 1376, panel «IVA Ventas e IVA Compras», cuadro «IVA ventas», línea 15: «Tasa mínima»', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '16', 'tax', 'IVA ventas — tasa básica', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 1376, panel «IVA Ventas e IVA Compras», cuadro «IVA ventas», línea 16: «Tasa básica»', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '18', 'total', 'Total IVA ventas (débito fiscal)', '{}'::jsonb, 80, null, array['15', '16']::text[], '{}'::text[], null, null, false, false, null, 'Formulario 1376, panel «IVA Ventas e IVA Compras», cuadro «IVA ventas», línea 18 «TOTAL»; retomado como primera línea del panel «Determinación de IVA» («IVA VENTAS»)', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '19', 'tax', 'IVA compras deducible por operaciones gravadas', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 1376, panel «Determinación de IVA», línea 19: «IVA COMPRAS deducible por operaciones gravadas». El formulario oficial reparte el crédito fiscal del período entre esta línea y la línea 27 (compras atribuibles a la exportación) mediante un cuadro de prorrateo sobre la composición de las ventas del ejercicio; este paquete no reproduce ese prorrateo — un contribuyente que también exporta declara aquí, de forma simplificada, la totalidad del crédito fiscal del período — véase «Lo que este paquete no transcribe» en el README', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '43', 'total', 'Saldo a pagar', '{}'::jsonb, 100, null, array['18']::text[], array['19']::text[], null, null, true, false, null, 'Formulario 1376, panel «Determinación de IVA», línea 43: «Saldo a pagar» — la diferencia positiva entre el IVA Ventas (línea 18) y el IVA Compras deducible (línea 19). El formulario oficial encadena antes de esta línea los excedentes de crédito fiscal de meses anteriores y otros créditos que este paquete no transcribe — véase el README', 'form1376-panel1'),
  ('UY', 'UY-F1376-IVA', '22', 'total', 'Crédito fiscal que pasa al próximo mes', '{}'::jsonb, 110, null, array['19']::text[], array['18']::text[], null, null, true, false, null, 'Formulario 1376, panel «Determinación de IVA», línea 22: «IVA COMPRAS excedente que pasa al próximo mes» — el remanente de crédito fiscal cuando el IVA Compras deducible (línea 19) excede el IVA Ventas (línea 18)', 'form1376-panel1')
on conflict (country, report_code, box, kind) do update set
