  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('UY-BAL', 'UY', 'default', 'Estado de Situación Patrimonial', 'balance_sheet', 'UY-Ekwo', date '1970-01-01', null, 'Ley N° 16.060, de Sociedades Comerciales, art. 87 — dentro de los cuatro meses de la fecha de cierre del ejercicio los administradores deben formular, cuando menos, el inventario y el balance general (estado de situación patrimonial y de resultados). Uruguay no fija una estructura de líneas obligatoria para ese balance fuera de las Normas Internacionales de Información Financiera que adopta el Decreto N° 291/014 para las empresas obligadas a aplicarlas (cuyo texto no se transcribe aquí): esta es la estructura mínima que Ekwo instala por defecto, agrupada por naturaleza (activo corriente, activo fijo, pasivo corriente, pasivo no corriente, patrimonio), sobre el plan de cuentas propio del paquete', 'ley16060'),
  ('UY-RES', 'UY', 'default', 'Estado de Resultados', 'income_statement', 'UY-Ekwo', date '1970-01-01', null, 'Ley N° 16.060, de Sociedades Comerciales, art. 90 — el estado de resultados del ejercicio debe indicar separadamente los resultantes de la actividad ordinaria de la sociedad y los provenientes de operaciones extraordinarias, discriminando los rubros positivos y negativos en la medida necesaria para permitir formarse un juicio claro sobre la magnitud y el contenido de cada uno de ellos. Estructura mínima propia de Ekwo, con los subtotales de utilidad bruta, operativa, antes de impuesto y neta', 'ley16060')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

