update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{NNNNNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Decreto N° 36/012, de 8 de febrero de 2012, y Resolución de la Dirección General Impositiva N° 798/012 — el Comprobante Fiscal Electrónico (CFE) se identifica por un tipo de comprobante, una serie y un número correlativo que el propio emisor electrónico asigna dentro del régimen que la Dirección General Impositiva autoriza, y que ésta valida mediante un Código de Autorización de Emisión (CAE) previamente otorgado por rangos — un mecanismo de autorización previa de numeración y reporte posterior, no la certificación documento a documento de un tercero como el PAC mexicano. El número que declara este paquete es el de la pieza contable, correlativo por diario, y no un número de un CAE que Ekwo no solicita: véase «Ekwo no emite un CFE uruguayo» en el README',
  numbering_source_key          = 'decreto36-012',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Texto Ordenado 2023, Título 10, art. 3° — el hecho gravado se considera configurado cuando el contrato o acto equivalente tenga ejecución mediante la entrega o la introducción de los bienes o la prestación de los servicios, pero «las entregas de bienes y prestaciones de servicios se presumirán realizadas en la fecha de la factura respectiva, sin perjuicio de las facultades de la Administración de fijar la misma, cuando existiera omisión, anticipación o retardo en la facturación». Este paquete declara invoice_if_issued por esa presunción legal, que hace coincidir en la generalidad de los casos la fecha del hecho gravado con la de la factura',
  tax_point_source_key          = 'to2023-t10',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Texto Ordenado 2023, Título 10, art. 3°, inciso quinto — el contribuyente tiene derecho a la deducción del impuesto facturado cuando la contraprestación no se hace efectiva por devolución de mercadería, bonificación, descuento o ajuste posterior de precio, entre otras causas, deducción que en la práctica documental del CFE y de todo comprobante fiscal se instrumenta mediante una nota de crédito que individualiza el comprobante que corrige. Un documento contabilizado se corrige con una nota de crédito que lo nombra, nunca con la edición del documento original',
  posted_edit_policy_source_key = 'to2023-t10',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Decreto N° 36/012, de 8 de febrero de 2012, que fija el régimen de documentación fiscal electrónica, y Resolución de la Dirección General Impositiva de Interés General N° 798/012, que lo implementa; la incorporación se extendió de forma escalonada desde 2012 según el volumen de ingresos del contribuyente hasta alcanzar, a partir del 1° de enero de 2025, a todos los contribuyentes del Impuesto al Valor Agregado, incluso los del IVA mínimo, con excepciones puntuales (actividad agropecuaria de reducida dimensión, agregación de valor en la construcción, contribuyentes del Impuesto a las Rentas de los No Residentes, Monotributo y Monotributo Social MIDES). El Comprobante Fiscal Electrónico (CFE) — e-Factura para operaciones entre contribuyentes, e-Ticket para el consumo final — se emite firmado electrónicamente por el emisor y validado mediante un Código de Autorización de Emisión (CAE) que la Dirección General Impositiva otorga por rangos, un régimen de autorización previa y reporte posterior más próximo al de Chile que a la certificación documento a documento de un tercero. La obligación es real y universal desde el 1° de enero de 2025 (con las excepciones puntuales arriba dichas), pero este paquete no puede escribirla en `mandatory_from`: ese campo exige un `profile` no nulo — un perfil construido sobre EN 16931 que una pieza de packages/formats escribe — y el CFE no lo es, por lo que `obligation: mandatory` tampoco puede declararse sin `mandatory_from`; véase «From Uruguay» en docs/international.md. EKWO NO SOLICITA CAE, NO FIRMA NI TRANSMITE CFE: ningún componente de packages/formats emite el XML del CFE uruguayo ni se comunica con la Dirección General Impositiva, y un documento emitido desde Ekwo no es un comprobante tributario uruguayo. El Registro Único Tributario (RUT) identifica a emisor y receptor y no tiene código ISO 6523 de la lista que el formato usa para party_scheme y vat_scheme',
  einvoice_source_key           = 'decreto36-012',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = array['csv']::text[],
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'UY';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('UY', 'cfe_not_issued', 'always', 'Este documento no es un Comprobante Fiscal Electrónico (CFE): no lleva Código de Autorización de Emisión (CAE) de la Dirección General Impositiva ni su representación validada. Sólo el CFE con CAE ampara la operación para efectos tributarios en Uruguay.', '{}'::jsonb, 10, date '1970-01-01', null, 'Decreto N° 36/012, de 8 de febrero de 2012, y Resolución de la Dirección General Impositiva N° 798/012, que fijan el régimen de documentación fiscal electrónica; desde el 1° de enero de 2025 todos los contribuyentes del Impuesto al Valor Agregado, incluidos los del IVA mínimo, revisten la calidad de emisores electrónicos desde su inscripción, salvo excepciones puntuales. Ekwo no solicita CAE, no firma ni transmite CFE: la frase evita que el documento que Ekwo produce se tome por el comprobante fiscal uruguayo'),
  ('UY', 'export', 'export', 'Exportación — operación no gravada por el Impuesto al Valor Agregado (artículo 5° del Título 10 del Texto Ordenado 2023).', '{}'::jsonb, 20, date '1970-01-01', null, 'Texto Ordenado 2023, Título 10, art. 5° — «Tampoco estarán gravadas aquellas exportaciones de bienes … y no lo estarán aquellas exportaciones de servicios que determine el Poder Ejecutivo», enumeradas por el Decreto N° 220/998, art. 34'),
  ('UY', 'exempt', 'exempt', 'Operación exonerada del Impuesto al Valor Agregado (artículo 38 del Título 10 del Texto Ordenado 2023).', '{}'::jsonb, 30, date '1970-01-01', null, 'Texto Ordenado 2023, Título 10, art. 38 — exoneraciones de determinados bienes, prestaciones de servicios e importaciones')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
